  const emails = [];
  matches.forEach((email) => {
    const key = email.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      emails.push(email);
    }
  });
  return emails.length ? emails.join("\n") : "No email addresses found.";
}

